def brightestPosition(lamps):
    delta = {}
    for pos, rad in lamps:
        delta[pos - rad] = delta.get(pos - rad, 0) + 1
        delta[pos + rad + 1] = delta.get(pos + rad + 1, 0) - 1
    best = 0
    answer = 0
    run = 0
    for x in sorted(delta):
        run += delta[x]
        if run > best:
            best = run
            answer = x
    return answer
